-- Generated by scripts/build-release.mjs from supabase/evolution/64_cm_tactics_drills.sql; edit that file instead.
-- Paste the WHOLE file in the Supabase SQL Editor and run it at once.
-- Not compared (intentionally compacted): mgr_lineups.
begin;
set local lock_timeout='5s';
set local statement_timeout='300s';
set local timezone='UTC';
drop table if exists public._release_protected_before;
create table public._release_protected_before(career_id uuid,table_name text,predicate text,cols text[],n bigint,hash text,primary key(career_id,table_name));
alter table public._release_protected_before enable row level security;
revoke all on public._release_protected_before from public,anon,authenticated;
do $$ declare c record;t record;pred text;h text;n bigint;begin
 perform 1 from public.careers order by id for update;
 for c in select id from public.careers order by id loop
  for t in select tab.table_name::text table_name,array_agg(col.column_name::text order by col.column_name) cols
   from information_schema.tables tab join information_schema.columns col using(table_schema,table_name)
   where tab.table_schema='public' and tab.table_type='BASE TABLE' and tab.table_name not in('_release_protected_before','mgr_lineups')
   group by tab.table_name order by tab.table_name loop
   pred:=case when t.table_name='careers' then 'id=$1' when 'career_id'=any(t.cols) then 'career_id=$1'
    when 'season_id'=any(t.cols) then 'season_id in(select id from public.career_seasons where career_id=$1)'
    when 'fixture_id'=any(t.cols) then 'fixture_id in(select f.id from public.season_fixtures f join public.career_seasons s on s.id=f.season_id where s.career_id=$1)' end;
   if pred is null then continue;end if;
   execute format('select count(*),md5(coalesce(string_agg(h,'''' order by h),'''')) from(select md5((select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(x)) e(k,v) where k=any($2))::text) h from public.%I x where %s)z',t.table_name,pred) into n,h using c.id,t.cols;
   insert into public._release_protected_before values(c.id,t.table_name,pred,t.cols,n,h);
  end loop;
 end loop;
end $$;
-- Evolução 64 — táticas, funções e exercícios pré-jogo do Championship Manager 17.
--  * As táticas passam a ser os 9 grupos do CM17: estilo, ataque, passe, desarme, ritmo, marcação, chutes longos,
--    bola parada e cruzamento. O motor continua lendo as chaves internas (mentality, build, width, pressing, line,
--    tackles, tempo), que agora são derivadas das escolhas do CM17. As chaves novas ganham efeito próprio no motor:
--    chutes de fora da área, cobranças de falta/escanteio que viram finalização e a parcela de cabeceios.
--  * Funções: capitão (+2% de rendimento do time com ele em campo) e batedores de falta e escanteio, que passam a
--    valer nas bolas paradas (o batedor de pênalti já valia desde a evolução 58).
--  * Exercícios pré-jogo (Tiro, Passe, Pênalti, Bloqueio, Roubada): comprados com moedas, dão bônus por 3 jogos.
-- Nada do progresso muda: táticas salvas são traduzidas para o equivalente do CM17.

-- ---------------------------------------------------------------- táticas: CM17 é a fonte, chaves internas derivadas
create or replace function public.mgr_tactics_clean(p_t jsonb)
returns jsonb language plpgsql immutable as $$
declare t jsonb:=coalesce(p_t,'{}'::jsonb); cm boolean; ment int; base int;
 style text; attack text; passing text; tackling text; tempo text; marking text; ls text; sp text; cr text;
begin
 cm:=t ?| array['style','attack','passing','tackling','marking','long_shots','set_pieces','crossing'];
 ment:=greatest(-2,least(2,coalesce((t->>'mentality')::int,0)));
 style:=case when t->>'style' in('defensive','neutral','attacking','counter') then t->>'style'
  when ment<0 then 'defensive' when ment>0 then 'attacking' else 'neutral' end;
 attack:=case when t->>'attack' in('left','right','both','central','mixed') then t->>'attack'
  else case t->>'width' when 'wide' then 'both' when 'center' then 'central' else 'mixed' end end;
 passing:=case when t->>'passing' in('short','mixed','long') then t->>'passing'
  else case t->>'build' when 'short' then 'short' when 'direct' then 'long' else 'mixed' end end;
 tackling:=case when t->>'tackling' in('light','balanced','heavy') then t->>'tackling'
  else case t->>'tackles' when 'cautious' then 'light' when 'aggressive' then 'heavy' else 'balanced' end end;
 tempo:=case when t->>'tempo' in('slow','normal','fast') then t->>'tempo' else 'normal' end;
 marking:=case when t->>'marking' in('low','medium','high') then t->>'marking'
  when t->>'pressing' in('low','medium','high') then t->>'pressing' else 'medium' end;
 ls:=case when t->>'long_shots' in('often','sometimes','rarely') then t->>'long_shots' else 'sometimes' end;
 sp:=case when t->>'set_pieces' in('shoot','cross','short') then t->>'set_pieces' else 'cross' end;
 cr:=case when t->>'crossing' in('byline','deep','mixed','rarely') then t->>'crossing'
  else case t->>'width' when 'wide' then 'byline' when 'center' then 'rarely' else 'mixed' end end;
 -- postura: o estilo manda; ±2 (usado pela IA no fim do jogo) é mantido quando tem o mesmo sentido do estilo
 base:=case style when 'defensive' then -1 when 'attacking' then 1 when 'counter' then -1 else 0 end;
 if style='counter' then ment:=least(0,coalesce((t->>'mentality')::int,-1));
 elsif cm and sign(ment)<>sign(base) then ment:=base;
 elsif sign(ment)<>sign(base) then ment:=base;
 end if;
 return jsonb_build_object(
  'style',style,'attack',attack,'passing',passing,'tackling',tackling,'tempo',tempo,'marking',marking,
  'long_shots',ls,'set_pieces',sp,'crossing',cr,
  'mentality',ment,
  'pressing',marking,
  'line',case when not cm and t->>'line' in('low','medium','high') then t->>'line' when marking='high' then 'high' when marking='low' or style='counter' then 'low' else 'medium' end,
  'build',case passing when 'short' then 'short' when 'long' then 'direct' else 'mixed' end,
  'width',case attack when 'central' then 'center' when 'mixed' then 'mixed' else 'wide' end,
  'tackles',case tackling when 'light' then 'cautious' when 'heavy' then 'aggressive' else 'normal' end,
  'manage',case when not cm and t->>'manage' in('keep','normal','push') then t->>'manage' else 'normal' end);
end $$;

-- IA no estilo contra-ataque declara o estilo do CM17 (transição rápida no motor)
do $$ declare src text;begin
 select pg_get_functiondef('public.mgr_ai_plan(uuid,text,numeric,boolean)'::regprocedure) into src;
 if src like '%"style":"counter"%' then return;end if;
 if position('when ''counter'' then ''{"pressing":"low","line":"low","build":"direct","tempo":"fast"}''::jsonb' in src)=0 then
  raise exception 'mgr_ai_plan diferente do esperado';
 end if;
 execute replace(src,'when ''counter'' then ''{"pressing":"low","line":"low","build":"direct","tempo":"fast"}''::jsonb',
  'when ''counter'' then ''{"pressing":"low","line":"low","build":"direct","tempo":"fast","style":"counter"}''::jsonb');
end $$;

-- ---------------------------------------------------------------- funções e exercícios
alter table public.cw_set_pieces add column if not exists captain text;

create table if not exists public.cw_drill_rules(
 kind text primary key check(kind in('shooting','passing','penalty','blocking','tackling')),
 label text not null,description text not null,price int not null check(price>0),games int not null check(games>0),sort_order int not null);
insert into public.cw_drill_rules(kind,label,description,price,games,sort_order) values
 ('shooting','Tiro','Finalização mais precisa nos próximos jogos.',40,3,1),
 ('passing','Passe','Mais criação e controle da posse.',40,3,2),
 ('penalty','Pênalti','Cobranças de pênalti e de falta mais certeiras.',40,3,3),
 ('blocking','Bloqueio','Goleiro e defesa mais seguros.',40,3,4),
 ('tackling','Roubada','Desarmes mais limpos e eficientes.',40,3,5)
on conflict(kind) do nothing;
create table if not exists public.cw_match_boosts(
 career_id uuid not null references public.careers(id) on delete cascade,
 kind text not null references public.cw_drill_rules(kind),
 games_left int not null default 0 check(games_left>=0),
 updated_at timestamptz not null default now(),
 primary key(career_id,kind));
alter table public.cw_drill_rules enable row level security;
alter table public.cw_match_boosts enable row level security;
revoke all on public.cw_drill_rules,public.cw_match_boosts from public,anon,authenticated;

-- "Ativar todos" sai com desconto (CM17: pacote de exercícios)
create or replace function public.cw_drill_all_price()
returns int language sql stable set search_path=public as $$
 select greatest(1,round(sum(price)*0.8)::int) from public.cw_drill_rules
$$;

create or replace function public.career_drills()
returns jsonb language plpgsql security definer set search_path=public as $$
declare car public.careers;
begin
 car:=public.mgr_lock();
 return jsonb_build_object('coins',(select coins from public.careers where id=car.id),'all_price',public.cw_drill_all_price(),
  'drills',(select jsonb_agg(jsonb_build_object('kind',r.kind,'label',r.label,'description',r.description,'price',r.price,'games',r.games,
    'games_left',coalesce(b.games_left,0)) order by r.sort_order)
   from public.cw_drill_rules r left join public.cw_match_boosts b on b.career_id=car.id and b.kind=r.kind));
end $$;

create or replace function public.career_drill_buy(p_kind text,p_request uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare car public.careers;prev jsonb;price int;kinds text[];
begin
 car:=public.mgr_lock();
 prev:=public.econ_request_get(car.id,p_request,'drill:'||coalesce(p_kind,''));
 if prev is not null then return prev;end if;
 if p_kind='all' then
  kinds:=array(select kind from public.cw_drill_rules order by sort_order);price:=public.cw_drill_all_price();
 else
  select array[kind],r.price into kinds,price from public.cw_drill_rules r where kind=p_kind;
  if kinds is null then raise exception 'Exercício inválido';end if;
 end if;
 if exists(select 1 from public.mgr_matches where career_id=car.id and status='live' and user_side is not null) then
  raise exception 'Exercícios pré-jogo só antes da partida';
 end if;
 perform public.econ_apply(car.id,'coins',-price,'match_drill',p_kind);
 insert into public.cw_match_boosts(career_id,kind,games_left)
 select car.id,r.kind,r.games from public.cw_drill_rules r where r.kind=any(kinds)
 on conflict(career_id,kind) do update set games_left=public.cw_match_boosts.games_left+excluded.games_left,updated_at=now();
 return public.econ_request_save(car.id,p_request,'drill:'||p_kind,public.career_drills()||jsonb_build_object('ok',true,'spent',price));
end $$;

-- batedores e capitão (o capitão chegou agora; o pedido antigo, sem ele, continua aceito pelo novo formato)
drop function if exists public.career_set_pieces_set(text,text,text);
create or replace function public.career_set_pieces_set(p_penalty text,p_free_kick text,p_corner text,p_captain text default null)
returns jsonb language plpgsql security definer set search_path=public as $$
declare car public.careers;own text;x text;
begin
 car:=public.mgr_lock();own:=public.cw_dev_own(car.id);
 foreach x in array array[p_penalty,p_free_kick,p_corner,p_captain] loop
  if x is not null and not exists(select 1 from public.mgr_players where career_id=car.id and player_id=x and club_id=own) then raise exception 'Jogador fora do seu elenco';end if;
 end loop;
 perform public.cw_dev_ensure_club(car.id,own);
 update public.cw_set_pieces set penalty=p_penalty,free_kick=p_free_kick,corner=p_corner,captain=p_captain where career_id=car.id and club_id=own;
 return jsonb_build_object('ok',true);
end $$;

do $$ declare src text;begin
 select pg_get_functiondef('public.career_club_dev_read()'::regprocedure) into src;
 if src like '%''captain'',sp.captain%' then return;end if;
 if position('''corner'',sp.corner)' in src)=0 then raise exception 'career_club_dev_read diferente do esperado';end if;
 execute replace(src,'''corner'',sp.corner)','''corner'',sp.corner,''captain'',sp.captain)');
end $$;

-- ---------------------------------------------------------------- partida: batedores, capitão e exercícios
create or replace function public.cw_cm_match_prepare(p_fixture bigint,p_career uuid,p_user_side character)
returns void language plpgsql security definer set search_path=public as $$
#variable_conflict use_column
declare m public.mgr_matches;f public.season_fixtures;sd text;club text;spr public.cw_set_pieces;
 fk jsonb:='{}';ck jsonb:='{}';form numeric[];spb numeric[];drills jsonb:='{}';k text;
begin
 select * into m from public.mgr_matches where fixture_id=p_fixture for update;
 if not found or coalesce((m.state->>'cm64')::boolean,false) or m.minute>0 then return;end if;
 select * into f from public.season_fixtures where id=p_fixture;
 form:=array[coalesce((m.state->'form'->>0)::numeric,1),coalesce((m.state->'form'->>1)::numeric,1)];
 spb:=array[coalesce((m.state->'sp_bonus'->>0)::numeric,0),coalesce((m.state->'sp_bonus'->>1)::numeric,0)];
 foreach sd in array array['h','a'] loop
  club:=case when sd='h' then f.home_club else f.away_club end;
  spr:=null;
  select * into spr from public.cw_set_pieces where career_id=p_career and club_id=club;
  -- batedor de falta: o escolhido; senão, o melhor em finalização+criação em campo
  fk:=fk||jsonb_build_object(sd,coalesce(
   (select player_id from public.mgr_match_players where fixture_id=p_fixture and side=sd and status='on' and player_id=spr.free_kick),
   (select player_id from public.mgr_match_players where fixture_id=p_fixture and side=sd and status='on' and pos<>'GOL' order by c_fin+c_cre desc limit 1)));
  ck:=ck||jsonb_build_object(sd,coalesce(
   (select player_id from public.mgr_match_players where fixture_id=p_fixture and side=sd and status='on' and player_id=spr.corner),
   (select player_id from public.mgr_match_players where fixture_id=p_fixture and side=sd and status='on' and pos<>'GOL' order by c_cre desc limit 1)));
  if spr.captain is not null and exists(select 1 from public.mgr_match_players where fixture_id=p_fixture and side=sd and status='on' and player_id=spr.captain) then
   form[case when sd='h' then 1 else 2 end]:=form[case when sd='h' then 1 else 2 end]*1.02;
  end if;
 end loop;
 -- exercícios pré-jogo só valem para o time do treinador e gastam um jogo cada
 if p_user_side in('h','a') then
  for k in select kind from public.cw_match_boosts where career_id=p_career and games_left>0 for update loop
   drills:=drills||jsonb_build_object(k,true);
   if k='shooting' then update public.mgr_match_players set c_fin=c_fin*1.06,c_att=c_att*1.03 where fixture_id=p_fixture and side=p_user_side;
   elsif k='passing' then update public.mgr_match_players set c_cre=c_cre*1.06,c_ctl=c_ctl*1.04 where fixture_id=p_fixture and side=p_user_side;
   elsif k='penalty' then spb[case when p_user_side='h' then 1 else 2 end]:=spb[case when p_user_side='h' then 1 else 2 end]+0.06;
   elsif k='blocking' then update public.mgr_match_players set c_gk=c_gk*1.06,c_def=c_def*1.03 where fixture_id=p_fixture and side=p_user_side;
   elsif k='tackling' then update public.mgr_match_players set c_tack=c_tack*1.08,c_def=c_def*1.03 where fixture_id=p_fixture and side=p_user_side;
   end if;
  end loop;
  update public.cw_match_boosts set games_left=games_left-1,updated_at=now() where career_id=p_career and games_left>0;
 end if;
 update public.mgr_matches set state=state||jsonb_build_object('cm64',true,'fk_taker',fk,'ck_taker',ck,'form',to_jsonb(form),
  'sp_bonus',to_jsonb(spb),'drills',drills) where fixture_id=p_fixture;
end $$;

do $$ begin
 if to_regprocedure('public.mgr_match_create_before_v64(bigint,uuid,character,jsonb)') is null then
  alter function public.mgr_match_create(bigint,uuid,character,jsonb) rename to mgr_match_create_before_v64;
 end if;
end $$;
create or replace function public.mgr_match_create(p_fixture bigint,p_career uuid,p_user_side character,p_user_lineup jsonb)
returns void language plpgsql security definer set search_path=public as $$
begin
 perform public.mgr_match_create_before_v64(p_fixture,p_career,p_user_side,p_user_lineup);
 perform public.cw_cm_match_prepare(p_fixture,p_career,p_user_side);
end $$;

-- ---------------------------------------------------------------- motor: chutes longos, bola parada, cruzamento, contra-ataque
do $$ declare src text;pairs text[][];i int;begin
 select pg_get_functiondef('public.mgr_engine_run_v2(bigint,integer,character)'::regprocedure) into src;
 if src like '%v_lsh%' then return;end if;
 pairs:=array[
  array[E'declare\n  v_pentaker text[];',
        E'declare\n  v_lsh float8[];\n  v_ldist boolean;\n  v_spk text[];\n  v_cprev int[];\n  v_fk int[];\n  v_fktaker text[];\n  v_cktaker text[];\n  v_sp64 int;\n  v_spq float8;\n  v_pentaker text[];'],
  array[E'  v_reload := true;\n  v_pentaker := array[',
        E'  v_cprev := array[v_corn[1], v_corn[2]]; v_fk := array[0, 0];\n  v_fktaker := array[v_m.state->''fk_taker''->>''h'', v_m.state->''fk_taker''->>''a''];\n  v_cktaker := array[v_m.state->''ck_taker''->>''h'', v_m.state->''ck_taker''->>''a''];\n  v_reload := true;\n  v_pentaker := array['],
  array['v_hdr := array[0.2, 0.2]; v_ctlm := array[1, 1];',
        E'v_hdr := array[0.2, 0.2]; v_ctlm := array[1, 1];\n      v_lsh := array[0.18, 0.18];\n      v_spk := array[coalesce(v_tac->''h''->>''set_pieces'',''cross''), coalesce(v_tac->''a''->>''set_pieces'',''cross'')];'],
  array['if v_hdr[s] = 0.10 then v_qual[s] := v_qual[s] + 0.02; end if;',
        E'if v_hdr[s] = 0.10 then v_qual[s] := v_qual[s] + 0.02; end if;\n'
        ||E'        -- CM17: cruzamento define a parcela de cabeceios; chutes longos trocam volume por qualidade\n'
        ||E'        v_hdr[s] := case v_tac -> (case when s = 1 then ''h'' else ''a'' end) ->> ''crossing'' when ''byline'' then 0.32 when ''deep'' then 0.24 when ''rarely'' then 0.06 else v_hdr[s] end;\n'
        ||E'        v_lsh[s] := case v_tac -> (case when s = 1 then ''h'' else ''a'' end) ->> ''long_shots'' when ''often'' then 0.35 when ''rarely'' then 0.06 else 0.18 end;\n'
        ||E'        if v_lsh[s] >= 0.35 then v_freq[s] := v_freq[s] * 1.04; elsif v_lsh[s] <= 0.06 then v_freq[s] := v_freq[s] * 0.97; v_qual[s] := v_qual[s] + 0.01; end if;\n'
        ||E'        if v_tac -> (case when s = 1 then ''h'' else ''a'' end) ->> ''style'' = ''counter'' then v_freq[s] := v_freq[s] * 1.06; v_qual[s] := v_qual[s] + 0.02; v_ctlm[s] := v_ctlm[s] * 0.95; end if;'],
  array['v_head := random() < v_hdr[s];',
        E'v_head := random() < v_hdr[s];\n        v_ldist := not v_head and random() < v_lsh[s];'],
  array['else power(v_p[i].aw + 0.05, 1.6) * power(v_p[i].fin / 60, 2) * (0.70 + 0.003 * v_p[i].cond) end',
        'else power(v_p[i].aw + 0.05 + case when v_ldist then 0.35 * v_p[i].cw else 0 end, 1.6) * power(v_p[i].fin / 60, 2) * (0.70 + 0.003 * v_p[i].cond) end'],
  array['- case when v_head then 0.08 else 0 end;',
        E'- case when v_head then 0.08 else 0 end\n                 - case when v_ldist then 0.13 - 0.002 * (v_p[v_k].fin - 65) else 0 end;'],
  array['if v_r < 0.20 then',
        'if v_r < (0.20 + case when v_ldist then 0.08 else 0 end) then'],
  array['case when v_head then ''de cabeça'' end);',
        'case when v_head then ''de cabeça'' when v_ldist then ''de fora da área'' end);'],
  array['if random() < 0.11 then                                         -- pênalti',
        E'if random() < 0.22 then v_fk[s] := v_fk[s] + 1; end if;           -- falta perigosa (bola parada)\n          if random() < 0.11 then                                         -- pênalti'],
  array['    -- ---- faltas no meio-campo e cartões (os dois times) ----',
        E'    -- ---- bolas paradas (CM17): faltas perigosas e escanteios viram finalização conforme a tática ----\n'
        ||E'    for s in 1 .. 2 loop\n'
        ||E'      d := 3 - s;\n'
        ||E'      v_sp64 := greatest(0, v_corn[s] - v_cprev[s]) + v_fk[s];\n'
        ||E'      while v_sp64 > 0 loop\n'
        ||E'        v_sp64 := v_sp64 - 1;\n'
        ||E'        v_side := case when s = 1 then ''h'' else ''a'' end;\n'
        ||E'        if v_fk[s] > 0 then v_fk[s] := v_fk[s] - 1; v_head := v_spk[s] = ''cross''; v_ldist := v_spk[s] = ''shoot'';\n'
        ||E'        else v_head := v_spk[s] <> ''short''; v_ldist := false; end if;\n'
        ||E'        v_w := ''{}'';\n'
        ||E'        for i in 1 .. v_n loop\n'
        ||E'          v_w := v_w || case when v_p[i].on_field and v_p[i].sd = s and v_p[i].pos <> ''GOL'' then\n'
        ||E'            case when v_ldist then power(v_p[i].fin / 60, 2) * power(v_p[i].cre / 60, 2) * case when v_p[i].pid = v_fktaker[s] then 60 else 1 end\n'
        ||E'                 when v_head then (v_p[i].aw + 0.5 * v_p[i].dw + 0.2) * power(v_p[i].head / 60, 3)\n'
        ||E'                 else power(v_p[i].aw + 0.05, 1.6) * power(v_p[i].fin / 60, 2) end else 0 end;\n'
        ||E'        end loop;\n'
        ||E'        v_k := public.mgr_pick(v_w);\n'
        ||E'        continue when v_k = 0;\n'
        ||E'        v_spq := case when v_ldist then 0.034 + 0.0018 * (v_p[v_k].fin - 65) + 0.0012 * (v_p[v_k].cre - 65)\n'
        ||E'                      when v_head then 0.018 + 0.0010 * (v_p[v_k].head - v_defav[d]) + case when v_cktaker[s] is not null then 0.004 else 0 end\n'
        ||E'                      else 0.012 end + 0.5 * v_spb[s];\n'
        ||E'        v_spq := greatest(0.005, least(0.15, v_spq));\n'
        ||E'        if random() < 0.55 then\n'
        ||E'          v_p[v_k].shots := v_p[v_k].shots + 1;\n'
        ||E'          if random() < v_spq / 0.55 then\n'
        ||E'            v_p[v_k].sot := v_p[v_k].sot + 1; v_p[v_k].goals := v_p[v_k].goals + 1; v_sc[s] := v_sc[s] + 1;\n'
        ||E'            perform public.mgr_event(p_fixture, v_min, v_side, ''goal'', v_p[v_k].pid, null, case when v_ldist then ''cobrança de falta'' when v_head then ''bola parada, de cabeça'' else ''bola parada'' end);\n'
        ||E'          elsif p_interactive is not null and random() < 0.5 then\n'
        ||E'            perform public.mgr_event(p_fixture, v_min, v_side, ''shot_off'', v_p[v_k].pid, null, case when v_ldist then ''cobrança de falta'' else ''bola parada'' end);\n'
        ||E'          end if;\n'
        ||E'        end if;\n'
        ||E'      end loop;\n'
        ||E'    end loop;\n'
        ||E'    v_cprev := array[v_corn[1], v_corn[2]];\n'
        ||E'    v_fk := array[0, 0];\n\n'
        ||'    -- ---- faltas no meio-campo e cartões (os dois times) ----']
 ];
 for i in 1..array_length(pairs,1) loop
  if (length(src)-length(replace(src,pairs[i][1],'')))/length(pairs[i][1])<>1 then
   raise exception 'Motor v2 diferente do esperado (trecho %); evolução 64 não aplicada',i;
  end if;
  src:=replace(src,pairs[i][1],pairs[i][2]);
 end loop;
 execute src;
end $$;

-- ---------------------------------------------------------------- conversão das táticas salvas
update public.mgr_lineups set tactics=public.mgr_tactics_clean(tactics) where not (tactics ? 'style');
-- Partidas em andamento seguem com a tática atual; o motor usa os padrões do CM17 até a próxima mudança.

revoke all on function public.cw_cm_match_prepare(bigint,uuid,character),public.cw_drill_all_price(),
 public.mgr_match_create_before_v64(bigint,uuid,character,jsonb) from public,anon,authenticated;
revoke all on function public.mgr_match_create(bigint,uuid,character,jsonb) from public,anon,authenticated;
revoke all on function public.career_drills(),public.career_drill_buy(text,uuid),public.career_set_pieces_set(text,text,text,text) from public,anon;
grant execute on function public.career_drills(),public.career_drill_buy(text,uuid),public.career_set_pieces_set(text,text,text,text) to authenticated;

notify pgrst,'reload schema';

do $$ declare r record;h text;n bigint;begin
 if not exists(select 1 from public._release_protected_before) and exists(select 1 from public.careers) then
  raise exception 'Snapshot de preservação ausente; execute o arquivo inteiro de uma vez';
 end if;
 for r in select * from public._release_protected_before order by career_id,table_name loop
  execute format('select count(*),md5(coalesce(string_agg(h,'''' order by h),'''')) from(select md5((select jsonb_object_agg(k,v) from jsonb_each(to_jsonb(x)) e(k,v) where k=any($2))::text) h from public.%I x where %s)z',r.table_name,r.predicate) into n,h using r.career_id,r.cols;
  if n<>r.n or h<>r.hash then raise exception 'Protected progress differs in table %; deployment rolled back',r.table_name;end if;
 end loop;
 raise notice 'Protected progress verified for % careers, % table comparisons',(select count(distinct career_id) from public._release_protected_before),(select count(*) from public._release_protected_before);
end $$;
drop table public._release_protected_before;
notify pgrst,'reload schema';
commit;
